void os64_libc_init(const os64_api_t*a){api=a;os64_libc_set_api(a);}void*malloc(size_t n){return api&&api->allocate?api->allocate(n):0;}void free(void*p){if(api&&api->deallocate)api->deallocate(p);}void*realloc(void*p,size_t n){return api&&api->reallocate?api->reallocate(p,n):0;}void*calloc(size_t c,size_t n){if(n&&c>(size_t)-1/n)return 0;size_t z=c*n;unsigned char*p=malloc(z);if(!p)return 0;for(size_t i=0;i<z;i++)p[i]=0;return p;}long strtol(const char*s,char**end,int base){long v=0;int neg=0;while(*s==' '||*s=='\t')s++;if(*s=='-'||*s=='+')neg=*s++=='-';if(base!=10){if(end)*end=(char*)s;return 0;}while(*s>='0'&&*s<='9'){v=v*10+(*s-'0');s++;}if(end)*end=(char*)s;return neg?-v:v;}int atoi(const char*s){return (int)strtol(s,0,10);}
